# -*- coding: utf-8 -*-
"""Makkah ziyarat in 7 languages: name (nm), summary (sum), facts, tips."""
MAKKAH = [
 {"q":"Masjid al-Haram, Makkah","ar":"الكعبة المشرفة والمسجد الحرام",
  "nm":{"en":"The Kaaba & Masjid al-Haram","ur":"کعبہ اور مسجد الحرام","hi":"काबा और मस्जिद-अल-हराम","bn":"কাবা ও মসজিদুল হারাম","tl":"Ang Kaaba at Masjid al-Haram","tr":"Kâbe ve Mescid-i Haram","id":"Ka'bah & Masjidil Haram"},
  "sum":{"en":"The House of Allah and the qiblah for every Muslim's prayer, at the heart of the Sacred Mosque.","ur":"اللہ کا گھر اور ہر مسلمان کی نماز کا قبلہ، مسجد الحرام کے بیچ میں۔","hi":"अल्लाह का घर और हर मुसलमान की नमाज़ का क़िबला, मस्जिद-अल-हराम के बीच में।","bn":"আল্লাহর ঘর এবং প্রত্যেক মুসলিমের নামাজের কিবলা, মসজিদুল হারামের কেন্দ্রে।","tl":"Ang Bahay ni Allah at ang qiblah ng dasal ng bawat Muslim, sa gitna ng Banal na Masjid.","tr":"Allah'ın evi ve her Müslümanın namazdaki kıblesi; Mescid-i Haram'ın kalbinde.","id":"Rumah Allah dan kiblat shalat setiap Muslim, di jantung Masjidil Haram."},
  "facts":{"en":["The Qur'an describes Ibrahim and Ismail (peace be upon them) raising the foundations of the House (2:127).","The Black Stone (al-Hajar al-Aswad) is set in the eastern corner, where each round of tawaf begins.","The semi-circular wall beside the Kaaba (Hijr Ismail, also called the Hatim) marks area that was part of the original Kaaba. Praying inside it counts as praying inside the Kaaba.","Maqam Ibrahim is the stone Ibrahim (AS) stood on while building the Kaaba; it is kept in a glass and gold case."],
   "ur":["قرآن میں ذکر ہے کہ ابراہیم اور اسماعیل علیہما السلام نے اس گھر کی بنیادیں اٹھائیں (2:127)۔","حجرِ اسود مشرقی کونے میں نصب ہے، جہاں سے طواف کا ہر چکر شروع ہوتا ہے۔","کعبہ کے ساتھ نیم دائرہ دیوار (حجرِ اسماعیل یا حطیم) اس حصے کو ظاہر کرتی ہے جو اصل کعبہ کا حصہ تھا۔ اس کے اندر نماز پڑھنا کعبہ کے اندر نماز پڑھنے کے برابر ہے۔","مقامِ ابراہیم وہ پتھر ہے جس پر کھڑے ہو کر ابراہیم علیہ السلام نے کعبہ تعمیر کیا؛ یہ شیشے اور سونے کے خول میں محفوظ ہے۔"],
   "hi":["क़ुरआन बताता है कि इब्राहीम और इस्माईल (अ.) ने इस घर की नींव उठाई (2:127)।","हजर-ए-असवद पूर्वी कोने में लगा है, जहाँ से तवाफ़ का हर चक्कर शुरू होता है।","काबा के पास अर्ध-गोलाकार दीवार (हिज्र-ए-इस्माईल या हतीम) उस हिस्से को दिखाती है जो असली काबा का हिस्सा था। इसके अंदर नमाज़ पढ़ना काबा के अंदर नमाज़ पढ़ने जैसा है।","मक़ाम-ए-इब्राहीम वह पत्थर है जिस पर खड़े होकर इब्राहीम (अ.) ने काबा बनाया; यह शीशे और सोने के खोल में रखा है।"],
   "bn":["কুরআনে আছে, ইব্রাহিম ও ইসমাইল (আ.) এই ঘরের ভিত্তি তুলেছিলেন (২:১২৭)।","হাজরে আসওয়াদ পূর্ব কোণে স্থাপিত, যেখান থেকে তাওয়াফের প্রতিটি চক্কর শুরু হয়।","কাবার পাশের অর্ধবৃত্তাকার দেয়াল (হিজরে ইসমাইল বা হাতিম) মূল কাবার অংশ ছিল এমন স্থান নির্দেশ করে। এর ভেতরে নামাজ পড়া কাবার ভেতরে নামাজ পড়ার মতো।","মাকামে ইব্রাহিম সেই পাথর, যার উপর দাঁড়িয়ে ইব্রাহিম (আ.) কাবা নির্মাণ করেছিলেন; এটি কাচ ও সোনার আবরণে রাখা।"],
   "tl":["Inilalarawan ng Qur'an sina Ibrahim at Ismail (sumakanila nawa ang kapayapaan) na itinataas ang pundasyon ng Bahay (2:127).","Ang Itim na Bato (al-Hajar al-Aswad) ay nasa silangang sulok, kung saan nagsisimula ang bawat ikot ng tawaf.","Ang pabilog na pader sa tabi ng Kaaba (Hijr Ismail o Hatim) ay bahagi ng orihinal na Kaaba. Ang pagdarasal sa loob nito ay parang pagdarasal sa loob ng Kaaba.","Ang Maqam Ibrahim ay ang batong tinayuan ni Ibrahim (AS) habang itinatayo ang Kaaba; nakalagay ito sa salamin at gintong lalagyan."],
   "tr":["Kur'an, Hz. İbrahim ve Hz. İsmail'in bu Evin temellerini yükselttiğini anlatır (2:127).","Hacerü'l-Esved doğu köşededir; tavafın her şavtı buradan başlar.","Kâbe'nin yanındaki yarım daire duvar (Hicr-i İsmail veya Hatîm), aslen Kâbe'nin parçası olan alanı gösterir. İçinde namaz kılmak Kâbe'nin içinde kılmak gibidir.","Makam-ı İbrahim, Hz. İbrahim'in Kâbe'yi inşa ederken üzerinde durduğu taştır; cam ve altın bir muhafaza içindedir."],
   "id":["Al-Qur'an mengisahkan Ibrahim dan Ismail (alaihimas salam) meninggikan fondasi Rumah ini (2:127).","Hajar Aswad terpasang di sudut timur, tempat setiap putaran tawaf dimulai.","Tembok setengah lingkaran di samping Ka'bah (Hijr Ismail atau Hathim) menandai area yang dulu bagian dari Ka'bah asli. Shalat di dalamnya seperti shalat di dalam Ka'bah.","Maqam Ibrahim adalah batu pijakan Ibrahim (AS) saat membangun Ka'bah; disimpan dalam kotak kaca dan emas."]},
  "tips":{"en":["The mataf (tawaf area) is usually least crowded late at night and mid-morning.","Zamzam water is available in coolers throughout the masjid."],
   "ur":["مطاف (طواف کی جگہ) میں عموماً رات دیر گئے اور دوپہر سے پہلے رش کم ہوتا ہے۔","پوری مسجد میں کولروں میں زمزم دستیاب ہے۔"],
   "hi":["मताफ़ (तवाफ़ की जगह) में आमतौर पर देर रात और दोपहर से पहले भीड़ कम होती है।","पूरी मस्जिद में कूलरों में ज़मज़म मिलता है।"],
   "bn":["মাতাফে (তাওয়াফের স্থান) সাধারণত গভীর রাতে ও সকালের মাঝামাঝি ভিড় কম থাকে।","পুরো মসজিদে কুলারে জমজম পাওয়া যায়।"],
   "tl":["Karaniwang pinakakaunti ang tao sa mataf (lugar ng tawaf) sa hatinggabi at kalagitnaan ng umaga.","May Zamzam sa mga cooler sa buong masjid."],
   "tr":["Metaf (tavaf alanı) genellikle gece geç saatlerde ve kuşluk vaktinde daha az kalabalıktır.","Zemzem, mescidin her yerindeki soğutucularda bulunur."],
   "id":["Mataf (area tawaf) biasanya paling sepi larut malam dan pertengahan pagi.","Air Zamzam tersedia di galon-galon di seluruh masjid."]}},
 {"q":"Zamzam Well, Makkah","ar":"بئر زمزم",
  "nm":{"en":"Zamzam Well","ur":"آبِ زمزم کا کنواں","hi":"ज़मज़म का कुआँ","bn":"জমজম কূপ","tl":"Balon ng Zamzam","tr":"Zemzem Kuyusu","id":"Sumur Zamzam"},
  "sum":{"en":"The blessed spring that Allah caused to flow for Hajar and her baby Ismail.","ur":"وہ مبارک چشمہ جو اللہ نے ہاجرہ اور ان کے بچے اسماعیل کے لیے جاری کیا۔","hi":"वह मुबारक चश्मा जो अल्लाह ने हाजरा और उनके बच्चे इस्माईल के लिए जारी किया।","bn":"সেই বরকতময় ঝরনা, যা আল্লাহ হাজেরা ও তাঁর শিশু ইসমাইলের জন্য প্রবাহিত করেছিলেন।","tl":"Ang pinagpalang bukal na pinadaloy ni Allah para kay Hajar at sa sanggol niyang si Ismail.","tr":"Allah'ın Hz. Hacer ve bebeği Hz. İsmail için akıttığı mübarek su.","id":"Mata air penuh berkah yang Allah alirkan untuk Hajar dan bayinya, Ismail."},
  "facts":{"en":["Hajar ran seven times between Safa and Marwah searching for water; Sa'i remembers her trust in Allah.","The Prophet ﷺ said: \"Zamzam water is for whatever it is drunk for\" (Sunan Ibn Majah).","The well is below the floor of the mataf and is no longer visible; the water is piped throughout the masjid."],
   "ur":["ہاجرہ نے پانی کی تلاش میں صفا اور مروہ کے درمیان سات چکر لگائے؛ سعی ان کے اللہ پر بھروسے کی یاد ہے۔","نبی ﷺ نے فرمایا: \"زمزم جس مقصد کے لیے پیا جائے اسی کے لیے ہے\" (سنن ابن ماجہ)۔","کنواں مطاف کے فرش کے نیچے ہے اور اب نظر نہیں آتا؛ اس کا پانی پائپوں کے ذریعے پوری مسجد میں پہنچایا جاتا ہے۔"],
   "hi":["हाजरा ने पानी की तलाश में सफ़ा और मरवा के बीच सात चक्कर लगाए; सई उनके अल्लाह पर भरोसे की याद है।","नबी ﷺ ने फ़रमाया: \"ज़मज़म जिस मक़सद से पिया जाए उसी के लिए है\" (सुनन इब्न माजह)।","कुआँ मताफ़ के फ़र्श के नीचे है और अब दिखाई नहीं देता; इसका पानी पाइपों से पूरी मस्जिद में पहुँचाया जाता है।"],
   "bn":["পানির খোঁজে হাজেরা সাফা ও মারওয়ার মাঝে সাতবার দৌড়েছিলেন; সাঈ আল্লাহর উপর তাঁর ভরসার স্মরণ।","নবী ﷺ বলেছেন: \"জমজম যে উদ্দেশ্যে পান করা হয় তার জন্যই\" (সুনান ইবনে মাজাহ)।","কূপটি মাতাফের মেঝের নিচে, এখন আর দেখা যায় না; এর পানি পাইপে পুরো মসজিদে পৌঁছানো হয়।"],
   "tl":["Tumakbo si Hajar nang pitong beses sa pagitan ng Safa at Marwah sa paghahanap ng tubig; ginugunita ng Sa'i ang kanyang pagtitiwala kay Allah.","Sinabi ng Propeta ﷺ: \"Ang tubig ng Zamzam ay para sa anumang layunin ng pag-inom nito\" (Sunan Ibn Majah).","Ang balon ay nasa ilalim ng sahig ng mataf at hindi na nakikita; dumadaloy ang tubig nito sa tubo sa buong masjid."],
   "tr":["Hz. Hacer su ararken Safa ile Merve arasında yedi kez koştu; sa'y onun Allah'a tevekkülünü hatırlatır.","Peygamber ﷺ şöyle buyurdu: \"Zemzem ne niyetle içilirse onun içindir\" (Sünen-i İbn Mâce).","Kuyu metafın zemini altındadır ve artık görülmez; suyu borularla mescidin her yerine ulaştırılır."],
   "id":["Hajar berlari tujuh kali antara Shafa dan Marwah mencari air; Sa'i mengenang tawakalnya kepada Allah.","Nabi ﷺ bersabda: \"Air Zamzam sesuai dengan niat peminumnya\" (Sunan Ibnu Majah).","Sumurnya berada di bawah lantai mataf dan tidak terlihat lagi; airnya dialirkan melalui pipa ke seluruh masjid."]},
  "tips":{"en":["Many pilgrims take Zamzam home; check your airline's rules for carrying it."],"ur":["بہت سے زائرین زمزم گھر لے جاتے ہیں؛ اپنی ایئرلائن کے اصول چیک کر لیں۔"],"hi":["बहुत से ज़ायरीन ज़मज़म घर ले जाते हैं; अपनी एयरलाइन के नियम जाँच लें।"],"bn":["অনেকে জমজম বাড়ি নিয়ে যান; আপনার এয়ারলাইনের নিয়ম দেখে নিন।"],"tl":["Maraming peregrino ang nag-uuwi ng Zamzam; suriin ang patakaran ng iyong airline."],"tr":["Pek çok hacı zemzemi eve götürür; havayolunuzun kurallarını kontrol edin."],"id":["Banyak jemaah membawa pulang Zamzam; periksa aturan maskapai Anda."]}},
 {"q":"Jabal al-Nour, Makkah","ar":"جبل النور وغار حراء",
  "nm":{"en":"Jabal al-Nour & Cave Hira","ur":"جبلِ نور اور غارِ حرا","hi":"जबल-ए-नूर और ग़ार-ए-हिरा","bn":"জাবালে নূর ও হেরা গুহা","tl":"Jabal al-Nour at Kuweba ng Hira","tr":"Nur Dağı ve Hira Mağarası","id":"Jabal Nur & Gua Hira"},
  "sum":{"en":"The Mountain of Light, where the first verses of the Qur'an were revealed in the Cave of Hira.","ur":"جبلِ نور، جہاں غارِ حرا میں قرآن کی پہلی آیات نازل ہوئیں۔","hi":"जबल-ए-नूर, जहाँ ग़ार-ए-हिरा में क़ुरआन की पहली आयतें नाज़िल हुईं।","bn":"নূর পাহাড়, যেখানে হেরা গুহায় কুরআনের প্রথম আয়াত নাযিল হয়েছিল।","tl":"Ang Bundok ng Liwanag, kung saan ipinahayag sa Kuweba ng Hira ang mga unang talata ng Qur'an.","tr":"Nur Dağı; Kur'an'ın ilk ayetlerinin indirildiği Hira Mağarası buradadır.","id":"Gunung Cahaya, tempat ayat-ayat pertama Al-Qur'an diturunkan di Gua Hira."},
  "facts":{"en":["Before prophethood, the Prophet ﷺ would spend time alone in the Cave of Hira, reflecting and worshipping.","Here the angel Jibril brought the first revelation: \"Read in the name of your Lord who created\" (96:1–5), around 610 CE.","From the cave, Masjid al-Haram can be seen in the distance."],
   "ur":["نبوت سے پہلے نبی ﷺ غارِ حرا میں تنہائی میں غور و فکر اور عبادت کیا کرتے تھے۔","یہیں جبرائیل علیہ السلام پہلی وحی لائے: \"پڑھو اپنے رب کے نام سے جس نے پیدا کیا\" (96:1–5)، تقریباً 610 عیسوی میں۔","غار سے دور مسجد الحرام نظر آتی ہے۔"],
   "hi":["नबुव्वत से पहले नबी ﷺ ग़ार-ए-हिरा में अकेले ग़ौर-ओ-फ़िक्र और इबादत करते थे।","यहीं जिब्रील (अ.) पहली वही लाए: \"पढ़ो अपने रब के नाम से जिसने पैदा किया\" (96:1–5), लगभग 610 ईस्वी में।","ग़ार से दूर मस्जिद-अल-हराम दिखाई देती है।"],
   "bn":["নবুয়তের আগে নবী ﷺ হেরা গুহায় একাকী চিন্তা ও ইবাদত করতেন।","এখানেই জিবরাইল (আ.) প্রথম ওহি নিয়ে আসেন: \"পড়ো তোমার রবের নামে, যিনি সৃষ্টি করেছেন\" (৯৬:১–৫), প্রায় ৬১০ খ্রিস্টাব্দে।","গুহা থেকে দূরে মসজিদুল হারাম দেখা যায়।"],
   "tl":["Bago ang pagkapropeta, ang Propeta ﷺ ay nag-iisa sa Kuweba ng Hira upang magnilay at sumamba.","Dito dinala ng anghel Jibril ang unang kapahayagan: \"Bumasa sa ngalan ng iyong Panginoon na lumikha\" (96:1–5), noong mga 610 CE.","Mula sa kuweba, tanaw sa malayo ang Masjid al-Haram."],
   "tr":["Peygamberlikten önce Peygamber ﷺ Hira Mağarası'nda yalnız kalıp tefekkür ve ibadet ederdi.","Cebrail ilk vahyi burada getirdi: \"Yaratan Rabbinin adıyla oku\" (96:1–5), yaklaşık MS 610'da.","Mağaradan uzakta Mescid-i Haram görülebilir."],
   "id":["Sebelum kenabian, Nabi ﷺ biasa menyendiri di Gua Hira untuk merenung dan beribadah.","Di sinilah Jibril membawa wahyu pertama: \"Bacalah dengan nama Tuhanmu yang menciptakan\" (96:1–5), sekitar tahun 610 M.","Dari gua, Masjidil Haram terlihat di kejauhan."]},
  "tips":{"en":["The climb is steep and takes most people around an hour each way. Go early or after Asr, wear good shoes and carry water.","Climbing is not a ritual of Umrah; it is a visit for reflection only."],
   "ur":["چڑھائی سخت ہے اور اکثر لوگوں کو ایک طرف تقریباً ایک گھنٹہ لگتا ہے۔ صبح سویرے یا عصر کے بعد جائیں، اچھے جوتے پہنیں اور پانی ساتھ رکھیں۔","یہاں چڑھنا عمرے کا رکن نہیں؛ یہ صرف غور و فکر کے لیے زیارت ہے۔"],
   "hi":["चढ़ाई कठिन है और ज़्यादातर लोगों को एक तरफ़ लगभग एक घंटा लगता है। सुबह जल्दी या अस्र के बाद जाएँ, अच्छे जूते पहनें और पानी रखें।","यहाँ चढ़ना उमराह का हिस्सा नहीं; यह सिर्फ़ ग़ौर-ओ-फ़िक्र की ज़ियारत है।"],
   "bn":["আরোহণ খাড়া, বেশিরভাগ মানুষের একদিকে প্রায় এক ঘণ্টা লাগে। ভোরে বা আসরের পর যান, ভালো জুতা পরুন ও পানি নিন।","এখানে ওঠা উমরাহর কোনো রুকন নয়; এটি কেবল চিন্তার জন্য জিয়ারত।"],
   "tl":["Matarik ang akyat at karaniwang isang oras bawat direksiyon. Pumunta nang maaga o pagkatapos ng Asr, magsuot ng magandang sapatos at magdala ng tubig.","Ang pag-akyat ay hindi ritwal ng Umrah; pagbisita lamang ito para magnilay."],
   "tr":["Tırmanış diktir ve çoğu kişi için gidiş-dönüş her biri yaklaşık bir saat sürer. Erken saatte veya ikindiden sonra gidin, iyi ayakkabı giyin ve su alın.","Tırmanmak umrenin bir parçası değildir; sadece tefekkür için bir ziyarettir."],
   "id":["Pendakiannya terjal, biasanya sekitar satu jam sekali jalan. Datang pagi-pagi atau setelah Ashar, pakai sepatu yang baik, dan bawa air.","Mendaki bukan bagian dari ritual Umrah; hanya ziarah untuk merenung."]}},
 {"q":"Jabal Thawr, Makkah","ar":"جبل ثور",
  "nm":{"en":"Jabal Thawr","ur":"جبلِ ثور","hi":"जबल-ए-सौर","bn":"জাবালে সাওর","tl":"Jabal Thawr","tr":"Sevr Dağı","id":"Jabal Tsur"},
  "sum":{"en":"The mountain where the Prophet ﷺ and Abu Bakr (RA) hid in a cave during the Hijrah.","ur":"وہ پہاڑ جہاں ہجرت کے دوران نبی ﷺ اور ابوبکر رضی اللہ عنہ ایک غار میں چھپے تھے۔","hi":"वह पहाड़ जहाँ हिजरत के दौरान नबी ﷺ और अबू बक्र (र.) एक ग़ार में छिपे थे।","bn":"সেই পাহাড়, যেখানে হিজরতের সময় নবী ﷺ ও আবু বকর (রা.) একটি গুহায় আত্মগোপন করেছিলেন।","tl":"Ang bundok kung saan nagtago ang Propeta ﷺ at si Abu Bakr (RA) sa isang kuweba noong Hijrah.","tr":"Hicret sırasında Peygamber ﷺ ile Hz. Ebû Bekir'in bir mağarada saklandığı dağ.","id":"Gunung tempat Nabi ﷺ dan Abu Bakar (RA) bersembunyi di sebuah gua saat Hijrah."},
  "facts":{"en":["The Prophet ﷺ and Abu Bakr (RA) hid in the cave for three nights while the Quraysh searched for them.","The Qur'an mentions this moment: \"…the second of two, when they were in the cave, and he said to his companion, 'Do not grieve; indeed Allah is with us'\" (9:40).","From here they set off for Madinah in 622 CE, the start of the Hijri calendar."],
   "ur":["قریش تلاش کرتے رہے اور نبی ﷺ اور ابوبکر رضی اللہ عنہ تین راتیں اس غار میں چھپے رہے۔","قرآن میں اس لمحے کا ذکر ہے: \"…وہ دو میں سے دوسرے تھے، جب دونوں غار میں تھے، جب وہ اپنے ساتھی سے کہہ رہے تھے: غم نہ کرو، بے شک اللہ ہمارے ساتھ ہے\" (9:40)۔","یہیں سے وہ 622 عیسوی میں مدینہ کے لیے روانہ ہوئے، جس سے ہجری کیلنڈر شروع ہوا۔"],
   "hi":["क़ुरैश तलाश करते रहे और नबी ﷺ और अबू बक्र (र.) तीन रातें इस ग़ार में छिपे रहे।","क़ुरआन में इस पल का ज़िक्र है: \"…वह दो में से दूसरे थे, जब दोनों ग़ार में थे, जब वह अपने साथी से कह रहे थे: ग़म न करो, बेशक अल्लाह हमारे साथ है\" (9:40)।","यहीं से वे 622 ईस्वी में मदीना के लिए रवाना हुए, जिससे हिजरी कैलेंडर शुरू हुआ।"],
   "bn":["কুরাইশরা খুঁজতে থাকে, আর নবী ﷺ ও আবু বকর (রা.) তিন রাত এই গুহায় লুকিয়ে ছিলেন।","কুরআনে এই মুহূর্তের উল্লেখ আছে: \"…তিনি ছিলেন দুজনের দ্বিতীয়জন, যখন তারা গুহায় ছিলেন, যখন তিনি সঙ্গীকে বলছিলেন: দুঃখ করো না, নিশ্চয়ই আল্লাহ আমাদের সঙ্গে আছেন\" (৯:৪০)।","এখান থেকেই তাঁরা ৬২২ খ্রিস্টাব্দে মদিনার পথে রওনা দেন, যা থেকে হিজরি সন শুরু।"],
   "tl":["Nagtago ang Propeta ﷺ at si Abu Bakr (RA) sa kuweba nang tatlong gabi habang hinahanap sila ng Quraysh.","Binanggit ng Qur'an ang sandaling ito: \"…ang ikalawa sa dalawa, nang sila'y nasa kuweba, nang sabihin niya sa kanyang kasama: 'Huwag kang malungkot; tunay na si Allah ay kasama natin'\" (9:40).","Mula rito sila umalis patungong Madinah noong 622 CE, ang simula ng kalendaryong Hijri."],
   "tr":["Kureyş onları ararken Peygamber ﷺ ve Hz. Ebû Bekir üç gece bu mağarada saklandı.","Kur'an bu anı anlatır: \"…ikinin ikincisi olarak, ikisi mağaradayken arkadaşına 'Üzülme, Allah bizimle beraberdir' diyordu\" (9:40).","Buradan MS 622'de Medine'ye doğru yola çıktılar; hicri takvim bu olayla başlar."],
   "id":["Nabi ﷺ dan Abu Bakar (RA) bersembunyi di gua selama tiga malam saat kaum Quraisy mencari mereka.","Al-Qur'an menyebut peristiwa ini: \"…salah seorang dari dua orang, ketika keduanya berada di gua, ketika dia berkata kepada sahabatnya: Jangan bersedih, sesungguhnya Allah bersama kita\" (9:40).","Dari sini mereka berangkat ke Madinah pada 622 M, awal kalender Hijriah."]},
  "tips":{"en":["The climb is longer and harder than Jabal al-Nour. Many visitors view the mountain from its base."],"ur":["یہاں کی چڑھائی جبلِ نور سے لمبی اور مشکل ہے۔ بہت سے لوگ نیچے سے ہی پہاڑ دیکھتے ہیں۔"],"hi":["यहाँ की चढ़ाई जबल-ए-नूर से लंबी और कठिन है। बहुत से लोग नीचे से ही पहाड़ देखते हैं।"],"bn":["এখানকার আরোহণ জাবালে নূরের চেয়ে দীর্ঘ ও কঠিন। অনেকে নিচ থেকেই পাহাড়টি দেখেন।"],"tl":["Mas mahaba at mas mahirap ang akyat kaysa Jabal al-Nour. Marami ang tumatanaw lamang mula sa paanan."],"tr":["Tırmanış Nur Dağı'ndan daha uzun ve zordur. Pek çok ziyaretçi dağı eteğinden izler."],"id":["Pendakiannya lebih panjang dan berat daripada Jabal Nur. Banyak pengunjung melihatnya dari kaki gunung."]}},
 {"q":"Mina, Makkah","ar":"منى",
  "nm":{"en":"Mina","ur":"منیٰ","hi":"मिना","bn":"মিনা","tl":"Mina","tr":"Mina","id":"Mina"},
  "sum":{"en":"The tent city east of Makkah where pilgrims stay during the days of Hajj.","ur":"مکہ کے مشرق میں خیموں کا شہر جہاں حج کے دنوں میں حاجی ٹھہرتے ہیں۔","hi":"मक्का के पूर्व में तंबुओं का शहर जहाँ हज के दिनों में हाजी ठहरते हैं।","bn":"মক্কার পূর্বে তাঁবুর শহর, যেখানে হজের দিনগুলোতে হাজিরা অবস্থান করেন।","tl":"Ang lungsod ng mga tolda sa silangan ng Makkah kung saan nananatili ang mga peregrino sa mga araw ng Hajj.","tr":"Mekke'nin doğusunda, hacıların hac günlerinde kaldığı çadır şehri.","id":"Kota tenda di timur Makkah tempat jemaah menginap selama hari-hari Haji."},
  "facts":{"en":["During Hajj, pilgrims stay in Mina and stone the Jamarat, three pillars marking where Ibrahim (AS) rejected Shaytan's whispers.","Masjid al-Khayf in Mina is where many prophets are reported to have prayed."],
   "ur":["حج کے دوران حاجی منیٰ میں ٹھہرتے ہیں اور جمرات کو کنکریاں مارتے ہیں، جو اس جگہ کی یاد ہیں جہاں ابراہیم علیہ السلام نے شیطان کے وسوسوں کو رد کیا۔","منیٰ کی مسجدِ خیف کے بارے میں روایت ہے کہ وہاں بہت سے انبیاء نے نماز پڑھی۔"],
   "hi":["हज के दौरान हाजी मिना में ठहरते हैं और जमरात पर कंकरियाँ मारते हैं, जो उस जगह की याद हैं जहाँ इब्राहीम (अ.) ने शैतान के वसवसों को ठुकराया।","मिना की मस्जिद-ए-ख़ैफ़ के बारे में रिवायत है कि वहाँ बहुत से नबियों ने नमाज़ पढ़ी।"],
   "bn":["হজের সময় হাজিরা মিনায় থাকেন এবং জামারাতে কংকর নিক্ষেপ করেন, যা স্মরণ করায় ইব্রাহিম (আ.) কোথায় শয়তানের কুমন্ত্রণা প্রত্যাখ্যান করেছিলেন।","মিনার মসজিদে খায়ফ সম্পর্কে বর্ণিত আছে যে সেখানে অনেক নবী নামাজ পড়েছেন।"],
   "tl":["Sa Hajj, nananatili ang mga peregrino sa Mina at binabato ang Jamarat, tatlong haligi na nagmamarka kung saan tinanggihan ni Ibrahim (AS) ang mga bulong ni Shaytan.","Ang Masjid al-Khayf sa Mina ay iniulat na pinagdasalan ng maraming propeta."],
   "tr":["Hac sırasında hacılar Mina'da kalır ve Hz. İbrahim'in şeytanın vesveselerini reddettiği yerleri simgeleyen üç Cemerât'ı taşlar.","Mina'daki Hayf Mescidi'nde pek çok peygamberin namaz kıldığı rivayet edilir."],
   "id":["Saat Haji, jemaah menginap di Mina dan melontar Jamarat, tiga tugu yang menandai tempat Ibrahim (AS) menolak bisikan setan.","Diriwayatkan banyak nabi pernah shalat di Masjid al-Khaif di Mina."]},
  "tips":{"en":["Outside Hajj season Mina is quiet; most visitors see it on a coach tour of the holy sites."],"ur":["حج کے موسم کے علاوہ منیٰ خاموش رہتا ہے؛ زیادہ تر لوگ زیارات کے بس ٹور میں اسے دیکھتے ہیں۔"],"hi":["हज के मौसम के अलावा मिना शांत रहता है; ज़्यादातर लोग ज़ियारत के बस टूर में इसे देखते हैं।"],"bn":["হজের মৌসুম ছাড়া মিনা নীরব থাকে; বেশিরভাগ মানুষ জিয়ারতের বাস ট্যুরে এটি দেখেন।"],"tl":["Sa labas ng panahon ng Hajj, tahimik ang Mina; karamihan ay nakikita ito sa bus tour ng mga banal na lugar."],"tr":["Hac mevsimi dışında Mina sakindir; çoğu ziyaretçi onu kutsal mekânlar otobüs turunda görür."],"id":["Di luar musim Haji, Mina sepi; kebanyakan pengunjung melihatnya saat tur bus ke tempat-tempat suci."]}},
 {"q":"Muzdalifah, Makkah","ar":"مزدلفة",
  "nm":{"en":"Muzdalifah","ur":"مزدلفہ","hi":"मुज़दलिफ़ा","bn":"মুজদালিফা","tl":"Muzdalifah","tr":"Müzdelife","id":"Muzdalifah"},
  "sum":{"en":"The open plain between Mina and Arafat where Hajj pilgrims spend the night under the sky.","ur":"منیٰ اور عرفات کے درمیان کھلا میدان جہاں حاجی آسمان تلے رات گزارتے ہیں۔","hi":"मिना और अराफ़ात के बीच खुला मैदान जहाँ हाजी आसमान के नीचे रात गुज़ारते हैं।","bn":"মিনা ও আরাফাতের মাঝে খোলা প্রান্তর, যেখানে হাজিরা খোলা আকাশের নিচে রাত কাটান।","tl":"Ang malawak na kapatagan sa pagitan ng Mina at Arafat kung saan nagpapalipas ng gabi ang mga peregrino ng Hajj.","tr":"Mina ile Arafat arasında, hacıların açık havada geceyi geçirdiği düzlük.","id":"Dataran terbuka antara Mina dan Arafah tempat jemaah haji bermalam di bawah langit."},
  "facts":{"en":["Pilgrims arrive after sunset on the Day of Arafah, pray Maghrib and Isha together and rest until dawn.","Many collect the small pebbles for stoning the Jamarat here.","The Qur'an mentions remembering Allah at al-Mash'ar al-Haram in Muzdalifah (2:198)."],
   "ur":["حاجی یومِ عرفہ کے غروب کے بعد یہاں پہنچتے ہیں، مغرب اور عشاء ایک ساتھ پڑھتے ہیں اور فجر تک آرام کرتے ہیں۔","بہت سے لوگ جمرات کے لیے کنکریاں یہیں سے چنتے ہیں۔","قرآن میں مزدلفہ کے مشعرِ حرام کے پاس اللہ کو یاد کرنے کا ذکر ہے (2:198)۔"],
   "hi":["हाजी यौम-ए-अरफ़ा के सूरज डूबने के बाद यहाँ पहुँचते हैं, मग़रिब और इशा साथ पढ़ते हैं और फ़ज्र तक आराम करते हैं।","बहुत से लोग जमरात के लिए कंकरियाँ यहीं से चुनते हैं।","क़ुरआन में मुज़दलिफ़ा के मशअर-ए-हराम के पास अल्लाह को याद करने का ज़िक्र है (2:198)।"],
   "bn":["আরাফার দিনের সূর্যাস্তের পর হাজিরা এখানে পৌঁছান, মাগরিব ও এশা একসঙ্গে পড়েন এবং ফজর পর্যন্ত বিশ্রাম নেন।","অনেকে এখান থেকেই জামারাতের কংকর সংগ্রহ করেন।","কুরআনে মুজদালিফার মাশআরুল হারামে আল্লাহকে স্মরণ করার কথা আছে (২:১৯৮)।"],
   "tl":["Dumarating ang mga peregrino pagkalubog ng araw sa Araw ng Arafah, sabay na nagdarasal ng Maghrib at Isha at nagpapahinga hanggang madaling-araw.","Marami ang nangongolekta rito ng maliliit na bato para sa Jamarat.","Binanggit ng Qur'an ang pag-alala kay Allah sa al-Mash'ar al-Haram sa Muzdalifah (2:198)."],
   "tr":["Hacılar Arefe günü güneş battıktan sonra gelir, akşam ve yatsıyı birlikte kılar ve sabaha kadar dinlenir.","Pek çok kişi Cemerât için taşları burada toplar.","Kur'an, Müzdelife'deki Meş'ar-i Haram'da Allah'ı anmayı zikreder (2:198)."],
   "id":["Jemaah tiba setelah matahari terbenam pada Hari Arafah, menjamak Maghrib dan Isya, lalu beristirahat hingga fajar.","Banyak yang mengumpulkan kerikil untuk melontar Jamarat di sini.","Al-Qur'an menyebut berdzikir kepada Allah di Masy'aril Haram di Muzdalifah (2:198)."]},
  "tips":{"en":["Usually seen from the coach on a ziyarat tour."],"ur":["عموماً زیارات کے ٹور میں بس سے دیکھا جاتا ہے۔"],"hi":["आमतौर पर ज़ियारत टूर में बस से देखा जाता है।"],"bn":["সাধারণত জিয়ারত ট্যুরে বাস থেকে দেখা হয়।"],"tl":["Karaniwang tinatanaw mula sa bus sa ziyarat tour."],"tr":["Genellikle ziyaret turunda otobüsten görülür."],"id":["Biasanya dilihat dari bus saat tur ziarah."]}},
 {"q":"Jabal al-Rahmah, Arafat","ar":"عرفات وجبل الرحمة",
  "nm":{"en":"Arafat & Jabal al-Rahmah","ur":"عرفات اور جبلِ رحمت","hi":"अराफ़ात और जबल-ए-रहमत","bn":"আরাফাত ও জাবালে রহমত","tl":"Arafat at Jabal al-Rahmah","tr":"Arafat ve Rahmet Dağı","id":"Arafah & Jabal Rahmah"},
  "sum":{"en":"The plain of Arafat, where standing on the 9th of Dhul Hijjah is the heart of Hajj.","ur":"میدانِ عرفات، جہاں 9 ذوالحجہ کا وقوف حج کی اصل ہے۔","hi":"अराफ़ात का मैदान, जहाँ 9 ज़िलहिज्जा का वुक़ूफ़ हज की जान है।","bn":"আরাফাতের ময়দান, যেখানে ৯ জিলহজ অবস্থান করা হজের মূল।","tl":"Ang kapatagan ng Arafat, kung saan ang pagtayo sa ika-9 ng Dhul Hijjah ang puso ng Hajj.","tr":"Arafat ovası; 9 Zilhicce'de burada vakfe haccın özüdür.","id":"Padang Arafah, tempat wukuf pada 9 Dzulhijjah yang merupakan inti ibadah Haji."},
  "facts":{"en":["The Prophet ﷺ said: \"Hajj is Arafah\" (Sunan at-Tirmidhi): the standing at Arafat is its essential pillar.","The Prophet ﷺ gave his Farewell Sermon at Arafat in 10 AH (632 CE).","Jabal al-Rahmah, the Mount of Mercy, is a small hill in the plain marked by a white pillar."],
   "ur":["نبی ﷺ نے فرمایا: \"حج عرفہ ہے\" (سنن ترمذی): عرفات کا وقوف حج کا بنیادی رکن ہے۔","نبی ﷺ نے 10 ہجری (632 عیسوی) میں عرفات میں خطبۂ حجۃ الوداع دیا۔","جبلِ رحمت میدان میں ایک چھوٹی پہاڑی ہے جس پر سفید ستون نصب ہے۔"],
   "hi":["नबी ﷺ ने फ़रमाया: \"हज अरफ़ा है\" (सुनन तिर्मिज़ी): अराफ़ात का वुक़ूफ़ हज का बुनियादी रुक्न है।","नबी ﷺ ने 10 हिजरी (632 ईस्वी) में अराफ़ात में ख़ुत्बा-ए-हज्जतुल विदा दिया।","जबल-ए-रहमत मैदान में एक छोटी पहाड़ी है जिस पर सफ़ेद खंभा लगा है।"],
   "bn":["নবী ﷺ বলেছেন: \"হজ হলো আরাফা\" (সুনান তিরমিজি): আরাফাতে অবস্থানই হজের মূল রুকন।","নবী ﷺ ১০ হিজরিতে (৬৩২ খ্রিস্টাব্দ) আরাফাতে বিদায় হজের ভাষণ দেন।","জাবালে রহমত ময়দানের একটি ছোট পাহাড়, যার উপর একটি সাদা স্তম্ভ আছে।"],
   "tl":["Sinabi ng Propeta ﷺ: \"Ang Hajj ay Arafah\" (Sunan at-Tirmidhi): ang pagtayo sa Arafat ang pangunahing haligi nito.","Ibinigay ng Propeta ﷺ ang kanyang Huling Sermon sa Arafat noong 10 AH (632 CE).","Ang Jabal al-Rahmah, ang Bundok ng Awa, ay maliit na burol sa kapatagan na may puting haligi."],
   "tr":["Peygamber ﷺ \"Hac Arafat'tır\" buyurdu (Sünen-i Tirmizî): Arafat vakfesi haccın temel rüknüdür.","Peygamber ﷺ Veda Hutbesi'ni hicri 10 (MS 632) yılında Arafat'ta irat etti.","Rahmet Dağı (Cebel-i Rahme), ovada beyaz bir sütunla işaretlenmiş küçük bir tepedir."],
   "id":["Nabi ﷺ bersabda: \"Haji adalah Arafah\" (Sunan at-Tirmidzi): wukuf di Arafah adalah rukun utamanya.","Nabi ﷺ menyampaikan Khutbah Perpisahan di Arafah pada 10 H (632 M).","Jabal Rahmah, Bukit Kasih Sayang, adalah bukit kecil di padang itu yang ditandai tugu putih."]},
  "tips":{"en":["Climbing Jabal al-Rahmah is not part of any ritual. Visit it simply to reflect and make dua."],"ur":["جبلِ رحمت پر چڑھنا کسی عبادت کا حصہ نہیں۔ صرف غور و فکر اور دعا کے لیے جائیں۔"],"hi":["जबल-ए-रहमत पर चढ़ना किसी इबादत का हिस्सा नहीं। सिर्फ़ ग़ौर-ओ-फ़िक्र और दुआ के लिए जाएँ।"],"bn":["জাবালে রহমতে ওঠা কোনো ইবাদতের অংশ নয়। শুধু চিন্তা ও দোয়ার জন্য যান।"],"tl":["Ang pag-akyat sa Jabal al-Rahmah ay hindi bahagi ng anumang ritwal. Bisitahin lamang para magnilay at mag-du'a."],"tr":["Rahmet Dağı'na çıkmak bir ibadet değildir. Sadece tefekkür ve dua için ziyaret edin."],"id":["Mendaki Jabal Rahmah bukan bagian dari ritual apa pun. Kunjungi sekadar untuk merenung dan berdoa."]}},
 {"q":"Masjid Aisha, Taneem, Makkah","ar":"مسجد عائشة (التنعيم)",
  "nm":{"en":"Masjid Aisha (Tan'eem)","ur":"مسجدِ عائشہ (تنعیم)","hi":"मस्जिद-ए-आयशा (तनईम)","bn":"মসজিদে আয়েশা (তানঈম)","tl":"Masjid Aisha (Tan'eem)","tr":"Hz. Âişe Mescidi (Ten'îm)","id":"Masjid Aisyah (Tan'im)"},
  "sum":{"en":"The nearest point outside the sacred boundary, where people in Makkah enter ihram for another Umrah.","ur":"حرم کی حد سے باہر قریب ترین مقام، جہاں مکہ میں موجود لوگ دوسرے عمرے کے لیے احرام باندھتے ہیں۔","hi":"हरम की हद से बाहर सबसे नज़दीकी जगह, जहाँ मक्का में मौजूद लोग दूसरे उमराह के लिए एहराम बाँधते हैं।","bn":"হারামের সীমানার বাইরে সবচেয়ে কাছের স্থান, যেখানে মক্কায় অবস্থানকারীরা আরেকটি উমরাহর জন্য ইহরাম বাঁধেন।","tl":"Ang pinakamalapit na lugar sa labas ng banal na hangganan, kung saan nag-iihram ang mga nasa Makkah para sa isa pang Umrah.","tr":"Harem sınırının dışındaki en yakın nokta; Mekke'dekiler başka bir umre için burada ihrama girer.","id":"Titik terdekat di luar batas tanah haram, tempat orang di Makkah berihram untuk Umrah berikutnya."},
  "facts":{"en":["During the Farewell Hajj, the Prophet ﷺ told Aisha (RA) to go with her brother Abdur-Rahman to Tan'eem to enter ihram for Umrah.","It is about 7 km from Masjid al-Haram, with washrooms and space to change into ihram."],
   "ur":["حجۃ الوداع میں نبی ﷺ نے عائشہ رضی اللہ عنہا کو ان کے بھائی عبدالرحمٰن کے ساتھ تنعیم جا کر عمرے کا احرام باندھنے کا حکم دیا۔","یہ مسجد الحرام سے تقریباً 7 کلومیٹر دور ہے، یہاں غسل خانے اور احرام بدلنے کی جگہ ہے۔"],
   "hi":["हज्जतुल विदा में नबी ﷺ ने आयशा (र.) को उनके भाई अब्दुर्रहमान के साथ तनईम जाकर उमराह का एहराम बाँधने को कहा।","यह मस्जिद-अल-हराम से लगभग 7 किमी दूर है, यहाँ ग़ुसलख़ाने और एहराम बदलने की जगह है।"],
   "bn":["বিদায় হজে নবী ﷺ আয়েশা (রা.)-কে তাঁর ভাই আবদুর রহমানের সঙ্গে তানঈমে গিয়ে উমরাহর ইহরাম বাঁধতে বলেন।","এটি মসজিদুল হারাম থেকে প্রায় ৭ কিমি দূরে, এখানে ওয়াশরুম ও ইহরাম পরার জায়গা আছে।"],
   "tl":["Sa Huling Hajj, sinabihan ng Propeta ﷺ si Aisha (RA) na sumama sa kapatid niyang si Abdur-Rahman sa Tan'eem upang mag-ihram para sa Umrah.","Mga 7 km ito mula sa Masjid al-Haram, may palikuran at lugar para magpalit ng ihram."],
   "tr":["Veda Haccı'nda Peygamber ﷺ Hz. Âişe'ye kardeşi Abdurrahman ile Ten'îm'e gidip umre için ihrama girmesini söyledi.","Mescid-i Haram'a yaklaşık 7 km uzaklıktadır; tuvaletler ve ihrama girmek için yer vardır."],
   "id":["Saat Haji Wada', Nabi ﷺ menyuruh Aisyah (RA) pergi bersama saudaranya, Abdurrahman, ke Tan'im untuk berihram Umrah.","Jaraknya sekitar 7 km dari Masjidil Haram, tersedia toilet dan tempat berganti ihram."]},
  "tips":{"en":["Taxis and buses run from near the Haram. Make your intention and start the Talbiyah here."],"ur":["حرم کے قریب سے ٹیکسیاں اور بسیں چلتی ہیں۔ یہیں نیت کریں اور تلبیہ شروع کریں۔"],"hi":["हरम के पास से टैक्सियाँ और बसें चलती हैं। यहीं नीयत करें और तल्बिया शुरू करें।"],"bn":["হারামের কাছ থেকে ট্যাক্সি ও বাস চলে। এখানেই নিয়ত করুন ও তালবিয়া শুরু করুন।"],"tl":["May taxi at bus mula malapit sa Haram. Dito gawin ang intensiyon at simulan ang Talbiyah."],"tr":["Harem yakınından taksi ve otobüsler kalkar. Niyetinizi burada edip telbiyeye başlayın."],"id":["Taksi dan bus tersedia dari dekat Haram. Berniatlah dan mulai Talbiyah di sini."]}},
 {"q":"Masjid al-Jiranah, Makkah","ar":"مسجد الجعرانة",
  "nm":{"en":"Masjid al-Ji'ranah","ur":"مسجدِ جعرانہ","hi":"मस्जिद-ए-जिराना","bn":"মসজিদে জিরানা","tl":"Masjid al-Ji'ranah","tr":"Ci'râne Mescidi","id":"Masjid Ji'ranah"},
  "sum":{"en":"A place outside the Haram boundary, north-east of Makkah, where the Prophet ﷺ entered ihram for Umrah.","ur":"مکہ کے شمال مشرق میں حدودِ حرم سے باہر ایک مقام، جہاں نبی ﷺ نے عمرے کا احرام باندھا۔","hi":"मक्का के उत्तर-पूर्व में हरम की हद से बाहर एक जगह, जहाँ नबी ﷺ ने उमराह का एहराम बाँधा।","bn":"মক্কার উত্তর-পূর্বে হারামের সীমানার বাইরে একটি স্থান, যেখানে নবী ﷺ উমরাহর ইহরাম বেঁধেছিলেন।","tl":"Isang lugar sa labas ng hangganan ng Haram, sa hilagang-silangan ng Makkah, kung saan nag-ihram ang Propeta ﷺ para sa Umrah.","tr":"Mekke'nin kuzeydoğusunda, Harem sınırının dışında, Peygamber ﷺ'in umre için ihrama girdiği yer.","id":"Tempat di luar batas tanah haram, di timur laut Makkah, tempat Nabi ﷺ berihram untuk Umrah."},
  "facts":{"en":["The Prophet ﷺ entered ihram here for Umrah after the Battle of Hunayn, in 8 AH.","It is further from the Haram than Tan'eem, so it is usually quieter."],
   "ur":["نبی ﷺ نے غزوۂ حنین کے بعد 8 ہجری میں یہاں سے عمرے کا احرام باندھا۔","یہ تنعیم سے زیادہ دور ہے، اس لیے یہاں عموماً رش کم ہوتا ہے۔"],
   "hi":["नबी ﷺ ने ग़ज़वा-ए-हुनैन के बाद 8 हिजरी में यहाँ से उमराह का एहराम बाँधा।","यह तनईम से ज़्यादा दूर है, इसलिए यहाँ आमतौर पर भीड़ कम होती है।"],
   "bn":["নবী ﷺ হুনাইনের যুদ্ধের পর ৮ হিজরিতে এখান থেকে উমরাহর ইহরাম বাঁধেন।","এটি তানঈমের চেয়ে দূরে, তাই সাধারণত ভিড় কম থাকে।"],
   "tl":["Dito nag-ihram ang Propeta ﷺ para sa Umrah pagkatapos ng Labanan sa Hunayn, noong 8 AH.","Mas malayo ito sa Haram kaysa Tan'eem, kaya karaniwang mas tahimik."],
   "tr":["Peygamber ﷺ Huneyn Savaşı'ndan sonra hicri 8 yılında burada umre için ihrama girdi.","Harem'e Ten'îm'den daha uzaktır, bu yüzden genellikle daha sakindir."],
   "id":["Nabi ﷺ berihram Umrah di sini setelah Perang Hunain, pada tahun 8 H.","Lokasinya lebih jauh dari Haram dibanding Tan'im, sehingga biasanya lebih sepi."]},
  "tips":{"en":["A good option for a second Umrah if Tan'eem is very busy."],"ur":["اگر تنعیم میں بہت رش ہو تو دوسرے عمرے کے لیے اچھا انتخاب ہے۔"],"hi":["अगर तनईम में बहुत भीड़ हो तो दूसरे उमराह के लिए अच्छा विकल्प है।"],"bn":["তানঈমে খুব ভিড় হলে দ্বিতীয় উমরাহর জন্য ভালো বিকল্প।"],"tl":["Magandang opsiyon para sa ikalawang Umrah kung napakasikip sa Tan'eem."],"tr":["Ten'îm çok kalabalıksa ikinci umre için iyi bir seçenektir."],"id":["Pilihan bagus untuk Umrah kedua jika Tan'im sangat ramai."]}},
 {"q":"Jannat al-Mualla, Makkah","ar":"جنة المعلاة",
  "nm":{"en":"Jannat al-Mu'alla","ur":"جنت المعلیٰ","hi":"जन्नतुल मुअल्ला","bn":"জান্নাতুল মুআল্লা","tl":"Jannat al-Mu'alla","tr":"Cennetü'l-Muallâ","id":"Jannatul Ma'la"},
  "sum":{"en":"The historic cemetery of Makkah, where Khadijah (RA), the Prophet's ﷺ first wife, is buried.","ur":"مکہ کا تاریخی قبرستان، جہاں نبی ﷺ کی پہلی زوجہ خدیجہ رضی اللہ عنہا مدفون ہیں۔","hi":"मक्का का ऐतिहासिक क़ब्रिस्तान, जहाँ नबी ﷺ की पहली ज़ौजा ख़दीजा (र.) दफ़्न हैं।","bn":"মক্কার ঐতিহাসিক কবরস্থান, যেখানে নবী ﷺ-এর প্রথম স্ত্রী খাদিজা (রা.) শায়িত।","tl":"Ang makasaysayang libingan ng Makkah, kung saan nakalibing si Khadijah (RA), ang unang asawa ng Propeta ﷺ.","tr":"Mekke'nin tarihî mezarlığı; Peygamber ﷺ'in ilk eşi Hz. Hatice burada medfundur.","id":"Pemakaman bersejarah Makkah, tempat Khadijah (RA), istri pertama Nabi ﷺ, dimakamkan."},
  "facts":{"en":["Khadijah (RA) was the first person to believe in the Prophet ﷺ and supported him through the early years of Islam.","Many members of the Prophet's ﷺ family from the Makkan period are buried here."],
   "ur":["خدیجہ رضی اللہ عنہا نبی ﷺ پر سب سے پہلے ایمان لائیں اور اسلام کے ابتدائی سالوں میں آپ ﷺ کا ساتھ دیا۔","مکی دور کے نبی ﷺ کے خاندان کے بہت سے افراد یہاں مدفون ہیں۔"],
   "hi":["ख़दीजा (र.) नबी ﷺ पर सबसे पहले ईमान लाईं और इस्लाम के शुरुआती सालों में आप ﷺ का साथ दिया।","मक्की दौर के नबी ﷺ के ख़ानदान के बहुत से लोग यहाँ दफ़्न हैं।"],
   "bn":["খাদিজা (রা.) সর্বপ্রথম নবী ﷺ-এর উপর ঈমান আনেন এবং ইসলামের প্রথম বছরগুলোতে তাঁকে সহায়তা করেন।","মক্কী যুগের নবী ﷺ-এর পরিবারের অনেক সদস্য এখানে শায়িত।"],
   "tl":["Si Khadijah (RA) ang unang naniwala sa Propeta ﷺ at sumuporta sa kanya sa mga unang taon ng Islam.","Maraming kapamilya ng Propeta ﷺ mula sa panahon ng Makkah ang nakalibing dito."],
   "tr":["Hz. Hatice, Peygamber ﷺ'e ilk iman eden kişidir ve İslam'ın ilk yıllarında ona destek oldu.","Mekke döneminden Peygamber ﷺ'in ailesinden pek çok kişi burada medfundur."],
   "id":["Khadijah (RA) adalah orang pertama yang beriman kepada Nabi ﷺ dan mendukung beliau di tahun-tahun awal Islam.","Banyak anggota keluarga Nabi ﷺ dari periode Makkah dimakamkan di sini."]},
  "tips":{"en":["Recite the dua for visiting graves. Graves are unmarked, so visit respectfully from the paths."],"ur":["قبرستان کی دعا پڑھیں۔ قبروں پر نام نہیں، اس لیے راستوں سے ادب کے ساتھ زیارت کریں۔"],"hi":["क़ब्रिस्तान की दुआ पढ़ें। क़ब्रों पर नाम नहीं हैं, इसलिए रास्तों से अदब के साथ ज़ियारत करें।"],"bn":["কবর জিয়ারতের দোয়া পড়ুন। কবরে নাম নেই, তাই পথ থেকে আদবের সঙ্গে জিয়ারত করুন।"],"tl":["Bigkasin ang du'a sa pagbisita sa libingan. Walang marka ang mga libingan, kaya bumisita nang magalang mula sa daanan."],"tr":["Kabir ziyareti duasını okuyun. Kabirler işaretsizdir; yollardan edeple ziyaret edin."],"id":["Bacalah doa ziarah kubur. Makam tidak bertanda, jadi berziarahlah dengan sopan dari jalan setapak."]}},
]
